<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, problem } from '../api'
import type { ApiProblem, Report } from '../types'
import { date, pretty, query, stateNames } from '../workbench'
import AsyncState from '../components/AsyncState.vue'
import RunPicker from '../components/RunPicker.vue'
import SummaryPanel from '../components/SummaryPanel.vue'
import VersionPanel from '../components/VersionPanel.vue'
import ReportChart from '../components/ReportChart.vue'
const route = useRoute(), router = useRouter(), report = ref<Report | null>(null), loading = ref(false), error = ref<ApiProblem | null>(null)
const run = computed(() => query(route.query.run_id) || query(route.query.run)), score = computed(() => query(route.query.score_set_id) || query(route.query.score_set)), compareRun = computed(() => query(route.query.compare_run_id) || query(route.query.compare)), compareScore = computed(() => query(route.query.compare_score_set_id))
let generation = 0
async function load() { const current = ++generation; report.value = null; error.value = null; if (!run.value) { loading.value = false; return }; loading.value = true; try { const result = await api.report(run.value, score.value, compareRun.value, compareScore.value); if (current === generation) report.value = result } catch (e) { if (current === generation) error.value = problem(e) } finally { if (current === generation) loading.value = false } }
function pick(id: string, selected: string) { void router.replace({ query: { ...route.query, run_id: id || undefined, score_set_id: selected || undefined, run: undefined, score_set: undefined } }) }
function pickCompare(id: string, selected: string) { void router.replace({ query: { ...route.query, compare_run_id: id || undefined, compare_score_set_id: selected || undefined, compare: undefined } }) }
watch(() => route.fullPath, load, { immediate: true })
</script>
<template><div class="page-heading"><div><div class="eyebrow">REPORT / TRACEABLE METRICS</div><h1>独立评测报告</h1><p>固定分母、有效样本与证据范围随结果一起展示。</p></div><ElButton :disabled="!run" @click="load">刷新报告</ElButton></div><section class="panel"><div class="panel-body compare-pickers"><RunPicker :run-id="run" :score-set-id="score" label="报告运行" @change="pick" /><RunPicker :run-id="compareRun" :score-set-id="compareScore" label="对照运行（可选）" allow-empty @change="pickCompare" /></div></section><AsyncState :loading="loading" :error="error" :empty="!run" empty-title="选择一条运行查看报告" empty-text="报告只展示持久化结果，没有运行时不会生成示例成绩。" @retry="load"><template #empty-action><RouterLink class="text-link" to="/experiments">前往实验创建运行</RouterLink></template><template v-if="report"><section class="panel section-gap"><div class="panel-heading"><div><h2>运行：{{ stateNames[report.run.status] || report.run.status }} <span class="count-label">{{ report.score_set.kind }} · 评分集：{{ stateNames[report.score_set.status] || report.score_set.status }}</span></h2><p class="small muted">{{ date(report.run.created_at) }} · {{ report.run.id }}</p></div><RouterLink class="text-link small" :to="{ path: '/evaluations', query: { run_id: report.run.id, score_set_id: report.score_set.id } }">查看全部用例 →</RouterLink></div><div class="panel-body"><SummaryPanel :summary="report.summary" /><div class="source-disclosure"><strong>来源与核验范围</strong><p class="small">{{ report.source_scope.real_quality_evidence ? '本运行有已核验的真实 Agent 与 Judge 质量证据。' : '本运行不满足完整真实质量证据条件；请查看模拟、协议替身与实际模型核验范围。' }}</p><details class="raw-detail"><summary>查看来源计数与覆盖范围</summary><pre>{{ pretty(report.source_scope) }}</pre></details></div><VersionPanel :value="report.version_verification" /><details class="raw-detail"><summary>当前评分集与冻结条件</summary><pre>{{ pretty({ score_set: report.score_set, snapshot_sha256: report.run.snapshot_sha256, snapshot: report.run.snapshot }) }}</pre></details></div></section><div v-if="report.comparison" class="comparison-notice"><strong>{{ report.comparison.comparable ? '相同数据与评分口径，共同有效样本可比较。' : '数据或评分口径不同，仅并排展示。' }}</strong><ul class="limitation-list"><li v-for="reason in report.comparison.limitations" :key="reason">{{ reason }}</li></ul><p class="small">实际版本：{{ report.comparison.version_comparison.status }}。差异不自动代表统计显著或线上效果提升。</p><RouterLink class="text-link small" :to="{ path: '/experiments', query: { left: report.run.id, right: compareRun, left_score: report.score_set.id, right_score: compareScore } }">查看比较条件与逐题差异 →</RouterLink></div><div class="charts-grid section-gap"><ReportChart :chart="report.charts.experiment_comparison" comparison :paired="report.comparison?.comparable" /><ReportChart :chart="report.charts.metric_changes" /><ReportChart :chart="report.charts.badcase_categories" /><ReportChart :chart="report.charts.latency_distribution" /></div></template></AsyncState></template>
